export function parseRanges(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Expected a string');
  }
  if (text.trim() === '') return [];

  const values = new Set();
  for (const item of text.split(',')) {
    const match = /^([+-]?[0-9]+)(?:\s*\.\.\s*([+-]?[0-9]+))?$/.exec(item.trim());
    if (!match) throw new RangeError('Invalid range syntax');

    const start = Number(match[1]);
    const end = match[2] === undefined ? start : Number(match[2]);
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
      throw new RangeError('Expected safe integers');
    }
    if (start > end) throw new RangeError('Descending range');
    const count = end - start + 1;
    if (count > 1000) throw new RangeError('Range exceeds 1000 members');

    for (let i = 0; i < count; i++) values.add(start + i);
  }
  return [...values].sort((a, b) => a - b);
}

export function createCache(capacity, now) {
  if (!Number.isSafeInteger(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive safe integer');
  }

  const entries = new Map();

  function purge(time) {
    for (const [key, entry] of entries) {
      if (time >= entry.expiration) entries.delete(key);
    }
  }

  return {
    set(key, value, ttl) {
      if (!Number.isFinite(ttl) || ttl < 0) {
        throw new RangeError('ttl must be finite and nonnegative');
      }

      const time = now();
      purge(time);
      entries.delete(key);
      if (ttl === 0) return;

      entries.set(key, { value, expiration: time + ttl });
      while (entries.size > capacity) {
        entries.delete(entries.keys().next().value);
      }
    },

    get(key) {
      const time = now();
      const entry = entries.get(key);
      if (entry === undefined) return undefined;
      if (time >= entry.expiration) {
        entries.delete(key);
        return undefined;
      }
      entries.delete(key);
      entries.set(key, entry);
      return entry.value;
    },

    has(key) {
      const time = now();
      const entry = entries.get(key);
      if (entry === undefined) return false;
      if (time >= entry.expiration) {
        entries.delete(key);
        return false;
      }
      return true;
    },

    get size() {
      purge(now());
      return entries.size;
    }
  };
}

export function memoizeAsync(fn) {
  const cache = new Map();

  return {
    get(key) {
      if (cache.has(key)) return cache.get(key);

      let resolve, reject;
      const promise = new Promise((res, rej) => {
        resolve = res;
        reject = rej;
      });

      cache.set(key, promise);
      promise.catch(() => {
        if (cache.get(key) === promise) cache.delete(key);
      });

      try {
        resolve(fn(key));
      } catch (error) {
        reject(error);
      }

      return promise;
    },

    invalidate(key) {
      cache.delete(key);
    },

    clear() {
      cache.clear();
    }
  };
}

export function createLedger(initial) {
  if (initial === null || typeof initial !== 'object') {
    throw new RangeError('Invalid initial accounts');
  }

  let balances = new Map();
  let remembered = new Map();

  for (const name of Object.keys(initial)) {
    const balance = initial[name];
    if (!Number.isSafeInteger(balance) || balance < 0) {
      throw new RangeError('Invalid balance');
    }
    balances.set(name, balance);
  }

  return {
    apply(batch) {
      if (!Array.isArray(batch)) throw new RangeError('Invalid batch');

      const nextBalances = new Map(balances);
      const nextRemembered = new Map(remembered);
      const statuses = [];

      for (const transfer of batch) {
        if (transfer === null || typeof transfer !== 'object') {
          throw new RangeError('Invalid transfer');
        }

        const { id, from, to, amount } = transfer;
        if (
          typeof id !== 'string' || id.length === 0 ||
          typeof from !== 'string' || !nextBalances.has(from) ||
          typeof to !== 'string' || !nextBalances.has(to) ||
          !Number.isSafeInteger(amount) || amount <= 0
        ) {
          throw new RangeError('Invalid transfer fields');
        }

        if (nextRemembered.has(id)) {
          const previous = nextRemembered.get(id);
          if (
            previous.from !== from || previous.to !== to ||
            previous.amount !== amount
          ) {
            throw new RangeError('Conflicting transfer id');
          }
          statuses.push('duplicate');
          continue;
        }

        const available = nextBalances.get(from);
        if (available < amount) {
          throw new RangeError('Insufficient balance');
        }

        if (from !== to) {
          const destination = nextBalances.get(to) + amount;
          if (!Number.isSafeInteger(destination)) {
            throw new RangeError('Destination balance overflow');
          }
          nextBalances.set(from, available - amount);
          nextBalances.set(to, destination);
        }

        nextRemembered.set(id, { from, to, amount });
        statuses.push('applied');
      }

      balances = nextBalances;
      remembered = nextRemembered;
      return statuses;
    },

    snapshot() {
      const result = Object.create(null);
      for (const [name, balance] of balances) {
        result[name] = balance;
      }
      return result;
    }
  };
}

